css:
@import url("https://fonts.googleapis.com/css2?family=Chivo:wght@400;500;700;900&display=swap");
:root{--yel:#FFE14D;--yel-l:#FFF6C4;--blk:#111111;--g1:#F4F4F1;--g2:#E6E6E1;--blue:#3D6DF2;--text:#1B1B1B;--muted:#62625C;--line:#DEDED8;
--font:"Chivo",system-ui,-apple-system,"Segoe UI",sans-serif;--wrap:1180px}
*,*::before,*::after{box-sizing:border-box}html{scroll-behavior:smooth}
body{margin:0;font-family:var(--font);font-size:18px;line-height:1.6;color:var(--text);background:#fff;-webkit-font-smoothing:antialiased}
img{max-width:100%;height:auto;display:block}a{color:inherit}p{margin:0 0 1em}
h1,h2,h3{font-weight:900;margin:0;line-height:1.02;color:var(--blk);letter-spacing:-.03em}h3{font-weight:700;letter-spacing:-.01em}
.wrap{max-width:var(--wrap);margin:0 auto;padding:0 22px}
.skip{position:absolute;left:-999px}.skip:focus{left:12px;top:12px;background:var(--yel);padding:10px;z-index:99}
:focus-visible{outline:3px solid var(--blue);outline-offset:3px;border-radius:6px}
.site-header{position:sticky;top:0;z-index:40;background:var(--yel);border-bottom:2px solid var(--blk)}
.nav{display:flex;align-items:center;justify-content:space-between;height:70px}
.logo{display:flex;align-items:center;gap:10px;font-weight:900;font-size:24px;text-decoration:none;color:var(--blk)}
.logo i{width:30px;height:24px;border:3px solid var(--blk);border-radius:5px;border-top-width:8px}
.menu{display:flex;gap:26px;list-style:none;margin:0;padding:0}.menu a{text-decoration:none;font-weight:700}.menu a:hover{text-decoration:underline;text-underline-offset:4px}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;padding:14px 24px;border-radius:10px;font-weight:700;text-decoration:none;border:2px solid var(--blk);font-family:var(--font);font-size:17px;cursor:pointer;box-shadow:4px 4px 0 var(--blk);transition:transform .12s,box-shadow .12s}
.btn:hover{transform:translate(2px,2px);box-shadow:2px 2px 0 var(--blk)}
.btn-blk{background:var(--blk);color:#fff}.btn-yel{background:var(--yel);color:var(--blk)}.btn-white{background:#fff;color:var(--blk)}
.burger{display:none;background:#fff;border:2px solid var(--blk);border-radius:8px;padding:8px 10px;cursor:pointer}.burger span{display:block;width:20px;height:2px;background:var(--blk);margin:4px 0}
.hero{background:var(--yel);padding:70px 0 0;border-bottom:2px solid var(--blk);overflow:hidden}
.hero-grid{display:grid;grid-template-columns:1fr 1.05fr;gap:40px;align-items:end}
.hero h1{font-size:clamp(46px,6.6vw,90px)}
.hero .lead{font-size:21px;max-width:40ch;margin:22px 0 30px;color:#2d2d2a}
.actions{display:flex;gap:14px;flex-wrap:wrap}
.also{margin-top:18px;font-size:15px;font-weight:500}
.users{display:flex;align-items:center;gap:10px;margin:30px 0 60px;font-weight:700}.users .st{letter-spacing:2px}
.browser{background:#fff;border:2px solid var(--blk);border-bottom:0;border-radius:16px 16px 0 0;overflow:hidden;position:relative}
.b-top{display:flex;align-items:center;gap:10px;background:var(--g1);border-bottom:2px solid var(--blk);padding:10px 14px}
.b-top i{width:11px;height:11px;border-radius:50%;border:2px solid var(--blk)}
.b-url{flex:1;background:#fff;border:2px solid var(--blk);border-radius:8px;padding:4px 12px;font-size:14px;color:var(--muted)}
.b-ext{width:28px;height:28px;border-radius:7px;background:var(--yel);border:2px solid var(--blk)}
.b-body{position:relative;height:430px}
.b-body img{width:100%;height:100%;object-fit:cover;filter:saturate(.7)}
.pop{position:absolute;right:16px;top:12px;width:300px;background:#fff;border:2px solid var(--blk);border-radius:14px;box-shadow:6px 6px 0 var(--blk);padding:16px}
.pop h3{font-size:17px;display:flex;justify-content:space-between;margin-bottom:10px}.pop h3 span{font-size:13px;font-weight:500;color:var(--muted)}
.save{width:100%;background:var(--blk);color:#fff;border:0;border-radius:8px;padding:10px;font:700 15px var(--font);margin-bottom:12px}
.grp{font-size:12px;font-weight:700;color:var(--muted);margin:10px 0 6px}
.tab{display:flex;align-items:center;gap:10px;padding:7px 8px;border-radius:8px;font-size:14px}
.tab:nth-child(odd){background:var(--g1)}
.tab i{width:16px;height:16px;border-radius:4px;flex:none}
.tab small{margin-left:auto;color:var(--muted)}
.press{padding:28px 0;border-bottom:2px solid var(--blk)}
.press .wrap{display:flex;justify-content:space-between;gap:24px;flex-wrap:wrap;align-items:center}
.press p{margin:0;font-weight:700}.press .row{display:flex;gap:40px;flex-wrap:wrap}.press span{font-weight:900;font-size:21px;color:#9E9E96}
section{padding:100px 0}
.head{max-width:720px;margin-bottom:50px}.head h2{font-size:clamp(38px,5vw,64px)}.head p{color:var(--muted);font-size:19px;margin-top:14px}
.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.card{border:2px solid var(--blk);border-radius:16px;padding:28px;background:#fff}
.card:nth-child(1),.card:nth-child(5){background:var(--yel-l)}
.card .ic{font-size:30px;display:block;margin-bottom:14px}
.card h3{font-size:22px;margin-bottom:8px}.card p{margin:0;color:var(--muted);font-size:16px}
.before{background:var(--g1);border-block:2px solid var(--blk)}
.ba{display:grid;grid-template-columns:1fr 1fr;gap:22px}
.ba div{border:2px solid var(--blk);border-radius:16px;padding:30px;background:#fff}
.ba div:last-child{background:var(--yel)}
.ba h3{font-size:26px;margin-bottom:14px}
.ba ul{margin:0;padding-left:20px;font-size:17px}.ba li{margin-bottom:8px}
.meter{display:flex;align-items:center;gap:14px;margin-top:22px;font-weight:700}
.meter span{flex:1;height:14px;border:2px solid var(--blk);border-radius:8px;overflow:hidden;background:#fff}.meter i{display:block;height:100%;background:var(--blk)}
.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;counter-reset:s}
.step{counter-increment:s;padding-top:10px}
.step::before{content:counter(s);display:grid;place-items:center;width:52px;height:52px;border-radius:50%;background:var(--yel);border:2px solid var(--blk);font-weight:900;font-size:22px;margin-bottom:16px}
.step h3{font-size:22px;margin-bottom:6px}.step p{margin:0;color:var(--muted)}
.reviews{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.rv{border:2px solid var(--blk);border-radius:16px;padding:26px;margin:0}
.rv .st{letter-spacing:2px}.rv p{margin:10px 0 14px}.rv cite{font-style:normal;font-weight:700}.rv cite span{display:block;font-weight:400;color:var(--muted);font-size:15px}
.plans{display:grid;grid-template-columns:1fr 1fr;gap:22px;max-width:860px}
.plan{border:2px solid var(--blk);border-radius:18px;padding:32px;display:flex;flex-direction:column}
.plan.pro{background:var(--yel);box-shadow:8px 8px 0 var(--blk)}
.plan h3{font-size:26px}.plan .amt{font-size:52px;font-weight:900;margin:10px 0 0}.plan .amt small{font-size:17px;font-weight:500;color:var(--muted)}
.plan ul{list-style:none;padding:0;margin:18px 0 26px}.plan li{padding:7px 0;border-bottom:1px dashed #b8b8ad}
.plan li::before{content:"✓";font-weight:900;margin-right:10px}
.plan .btn{margin-top:auto}
.faq{max-width:820px}
.faq details{border-bottom:2px solid var(--blk);padding:20px 0}
.faq summary{list-style:none;cursor:pointer;font-weight:700;font-size:20px;display:flex;justify-content:space-between;gap:18px}
.faq summary::-webkit-details-marker{display:none}.faq summary::after{content:"+";font-size:28px;line-height:1;font-weight:900}
.faq details[open] summary::after{content:"−"}.faq details p{margin:10px 0 0;color:var(--muted)}
.cta{background:var(--blk);color:#dcdcd6;text-align:center}
.cta h2{color:#fff;font-size:clamp(40px,5.6vw,72px);max-width:14ch;margin:0 auto}.cta p{font-size:20px;margin:18px 0 30px}
.cta .btn{box-shadow:4px 4px 0 var(--yel)}
footer{padding:34px 0;color:var(--muted);font-size:15px}
.foot{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;align-items:center}
footer ul{list-style:none;padding:0;margin:0;display:flex;gap:22px;flex-wrap:wrap}footer a{text-decoration:none}footer a:hover{color:var(--blk)}
@media (max-width:1000px){.menu,.nav>.btn{display:none}.burger{display:block}
.menu.open{display:flex;flex-direction:column;position:absolute;top:70px;left:0;right:0;background:var(--yel);padding:22px;border-bottom:2px solid var(--blk);gap:16px}
.hero-grid{grid-template-columns:1fr}.grid,.reviews,.steps{grid-template-columns:1fr 1fr}}
@media (max-width:600px){body{font-size:17px}section{padding:72px 0}.grid,.reviews,.steps,.ba,.plans{grid-template-columns:1fr}.pop{width:auto;left:12px;right:12px}.b-body{height:470px}}
